import type { D1AuthoredBank } from '../corpus'

export const LEMBAH_AWAN_D_R8: D1AuthoredBank = {
  universeId: 'lembah-awan',
  rubricId: 'D-R8',
  STRONG: [
    { chapters: [
      { chapterNumber: 41, title: 'Bambu Melenting di Lereng', paragraphs: ['Karsa menemukan tiga bilah bambu penahan tanah melenting menjauhi lereng setelah kru Bagas menancapkan tiang berat di atas kebun kopi. Retakan tipis membelah jalan menuju sekolah. Vina memasang bilah tambahan pada jarak satu depa, lalu meminta Bu Ningsih memindahkan murid dari ruang paling dekat tebing sebelum kantor menyebut retakan itu biasa.'] },
      { chapterNumber: 42, title: 'Kelereng Bergerak Sendiri', paragraphs: ['Bu Ningsih meletakkan kelereng murid pada lantai kelas dan semuanya menggelinding ke dinding lereng. Vina mengukur pergeseran bilah dengan benang, sementara para orang tua memindahkan buku ke balai. Sekolah belum runtuh, namun lantai miring dan bambu membuktikan tanah terus bergerak. Mereka harus memilih tempat aman sebelum hujan berikutnya tiba.'] },
      { chapterNumber: 43, title: 'Cekungan di Kebun Vina', paragraphs: ['Mbah Ripto menunjukkan cekungan kosong di bawah teras Vina yang dapat menerima lumpur bila jalurnya dibuka. Jalur terpendek melewati tungku pengering kopi warisan ayahnya. Bu Ningsih menolak meminta pengorbanan itu dan mengusulkan evakuasi panjang. Vina menandai arah aliran dengan sekam, tetapi belum sanggup menjawab apa yang rela ia hilangkan.'] },
      { chapterNumber: 44, title: 'Latihan Turun Tanpa Panik', paragraphs: ['Anak-anak berlatih meninggalkan kelas melalui kebun pisang, dipandu tali yang dipasang Karsa. Dua murid kecil tersandung saat orang dewasa berteriak, sehingga Bu Ningsih mengulang latihan dalam diam memakai ketukan kaleng. Vina menyiapkan cangkul dekat tungku. Persiapan itu menyelamatkan waktu, tetapi tidak menghentikan massa tanah yang semakin menekan bilah bambu.'] },
      { chapterNumber: 45, title: 'Bagas Menarik Pekerjanya', paragraphs: ['Bagas menarik semua pekerja dari lereng dan melarang kayu kantor dipakai menyangga sekolah. Ia menawarkan truk untuk memindahkan keluarga Vina bila mereka menyerahkan cekungan kepada kebun teh. Vina menolak tawaran itu. Bu Ningsih marah karena penolakannya mempertaruhkan murid, lalu keduanya berpisah tanpa sepakat apakah sekolah atau rumah harus dikorbankan.'] },
      { chapterNumber: 46, title: 'Hujan Mematahkan Dua Bilah', paragraphs: ['Hujan malam mematahkan dua bilah dan mendorong tanah sampai pagar sekolah. Bu Ningsih menutup kelas sepenuhnya, sedangkan warga menggali parit pemecah lumpur menuju cekungan. Ujung parit berhenti di dinding teras Vina. Danu menawarkan membongkar tungku sendiri, tetapi Vina meminta semua orang menunggu sampai murid serta keluarga bawah selesai dievakuasi.'] },
      { chapterNumber: 47, title: 'Tungku Warisan Dirobohkan', paragraphs: ['Ketika derak terdengar dari punggung lereng, Vina mengayunkan palu ke tungku pengering keluarganya. Danu dan Karsa merobohkan bata lain, lalu membuka dinding teras selebar dua depa. Lumpur pertama menerobos bekas tungku menuju cekungan. Bu Ningsih membawa murid terakhir turun sambil melihat kebun kopi Vina terbelah oleh aliran cokelat.'] },
      { chapterNumber: 48, title: 'Sekolah Berdiri Tanpa Halaman', paragraphs: ['Longsor berhenti di cekungan setelah meratakan tungku, petak kopi, dan separuh halaman sekolah. Ruang kelas masih berdiri, tetapi Vina kehilangan tempat mengeringkan panen serta pohon terbaik keluarganya. Bu Ningsih meminta maaf karena sempat menjadikan pilihan itu beban Vina seorang. Mereka sepakat sekolah baru tidak boleh dibangun kembali tepat di kaki lereng.'] },
      { chapterNumber: 49, title: 'Kelas Dibuka di Balai', paragraphs: ['Pelajaran dimulai di balai dengan meja tidak seragam dan dinding tanpa jendela. Anak-anak menggambar posisi bilah bambu, bukan untuk memuji bencana, melainkan memahami mengapa tanah bergerak. Vina menjual sisa kopi basah dengan harga rendah. Bu Ningsih menyisihkan sudut kelas untuk rencana tungku bersama yang kelak dapat dipakai semua penanam.'] },
      { chapterNumber: 50, title: 'Lingkar Bata Menampung Hujan', paragraphs: ['Kecamatan melarang pemasangan tiang baru dan menetapkan cekungan sebagai ruang penahan longsor. Sekolah tetap belajar di balai sampai bangunan aman tersedia. Vina menanam kopi pada petak sempit bersama Danu, tanpa janji panen cepat. Di bekas tungku ayah mereka, lingkar bata yang tersisa menampung air hujan sementara bilah bambu baru berdiri lurus di lereng.'] },
    ], justification: 'The ending makes measured slope movement force Vina to destroy her inherited drying kiln and terrace, saving the school while leaving durable economic and spatial loss.' },
    { chapters: [
      { chapterNumber: 41, title: 'Abu Hangat di Daun', paragraphs: ['Abu hangat menempel pada daun teh yang basah meski tidak ada tungku desa menyala. Vina mengikuti serpihannya sampai batas kebun dan menemukan rumput kering sengaja dibiarkan menyambung ke lumbung. Karsa mengenali bekas sabit buatannya pada batang yang dipangkas. Keduanya menduga seseorang menyiapkan jalan api sebelum angin timur menguat.'] },
      { chapterNumber: 42, title: 'Garis Rumput Diputus', paragraphs: ['Vina mengajak keluarga lereng mencabut rumput sepanjang batas rumah, tetapi Karsa menolak memimpin. Ia mengaku pernah menjual enam sabit kepada kru Bagas tanpa menanyakan kegunaannya. Warga mulai meragukannya. Vina meminta Karsa menunjukkan cara membaca arah pangkasan, lalu membiarkan setiap keluarga memeriksa pekarangannya sendiri sebelum memutuskan apakah ia masih layak dipercaya.'] },
      { chapterNumber: 43, title: 'Sekat Pertama Terlalu Sempit', paragraphs: ['Karsa membuat sekat tanah kupas selebar dua langkah di belakang balai. Mereka membakar segenggam ilalang untuk mengujinya, namun bara terbang melewati batas dan menghanguskan pagar kosong. Vina memadamkan api bersama para ibu. Kegagalan itu memaksa Karsa mengakui bahwa angin puncak membutuhkan sekat jauh lebih lebar daripada lahan yang rela diserahkan warga.'] },
      { chapterNumber: 44, title: 'Gentong Berbaris di Punggung', paragraphs: ['Warga menaruh gentong air dan karung tanah di punggung kebun sambil memangkas ranting rendah. Bu Ningsih melatih anak-anak menuju sawah basah bila kentongan berbunyi tiga kali. Bagas menyebut persiapan itu hasutan dan melarang pekerja kebun membantu. Vina tetap membagi kelompok jaga, sedangkan Karsa menandai arah angin dengan pita daun pisang.'] },
      { chapterNumber: 45, title: 'Bengkel Dilempari Jelaga', paragraphs: ['Seseorang melempar jelaga bercampur minyak ke dinding bengkel Karsa pada malam hari. Karsa ingin pergi dari lembah sebelum kebakaran dan berkata semua orang akan menuduhnya bila api muncul. Vina tidak menghapus kesalahannya menjual sabit, tetapi meminta ia memilih apakah pengetahuan tangannya akan dipakai untuk meninggalkan warga atau menyiapkan pertahanan terakhir.'] },
      { chapterNumber: 46, title: 'Angin Membalik Pita Daun', paragraphs: ['Pita daun pisang mendadak mengarah ke rumah-rumah saat angin timur berbelok. Sekat aman kini harus melewati kebun teh Vina yang siap dipetik. Danu menolak karena panen itu membayar kebutuhan mereka sampai musim hujan. Karsa menawarkan membuat bakar-balik lebih dekat lumbung, tetapi percobaan pagar hangus membuktikan jarak tersebut tidak cukup.'] },
      { chapterNumber: 47, title: 'Api Muncul dari Puncak', paragraphs: ['Asap hitam naik dari punggung kebun ketika anak-anak telah turun ke sawah. Kelompok jaga memukul kentongan dan membasahi atap, sementara lidah api mengikuti rumput menuju lumbung. Vina berdiri di batas tanaman keluarganya dengan obor. Danu menyerahkan kendi minyak tanpa menyetujui kehilangan itu, lalu memilih membantu menjaga arah bakar-balik bersama Karsa.'] },
      { chapterNumber: 48, title: 'Kebun Sendiri Dibakar', paragraphs: ['Vina menyalakan baris teh miliknya dari sisi bawah. Karsa dan Danu menjaga api kecil bergerak melawan angin hingga bertemu kebakaran dari puncak. Seluruh pucuk siap petik menjadi batang hitam, tetapi api utama kehilangan bahan sebelum mencapai lumbung. Saat hujan abu reda, Vina tidak memiliki panen untuk dibawa pulang.'] },
      { chapterNumber: 49, title: 'Palu Menempa Cangkul Hangus', paragraphs: ['Karsa membuka bengkel dan mengumpulkan cangkul yang gagangnya terbakar untuk diperbaiki tanpa biaya. Ia mengaku di depan warga bahwa sabit buatannya membantu membuka jalur api, lalu menyerahkan nama pembelinya kepada kepala desa. Vina menyapu abu dari lantai lumbung. Kejujuran Karsa tidak mengembalikan kebunnya, tetapi membuat tanggung jawab tidak lagi ditanggung satu keluarga.'] },
      { chapterNumber: 50, title: 'Tunas Merah di Tanah Hitam', paragraphs: ['Penyelidikan desa menemukan minyak tersimpan di pondok kru Bagas, sementara lumbung tetap berdiri dan rumah lereng selamat. Vina bekerja memetik di kebun tetangga karena lahannya belum menghasilkan. Karsa menancapkan arit pada batas sekat sebagai pengingat pemeriksaan musim depan. Di antara batang teh hitam, tunas merah pertama muncul tanpa menjanjikan panen yang cepat.'] },
    ], justification: 'The ending builds toward a controlled counterfire that costs Vina her own harvest, saves the settlement, and makes Karsa answer openly for the tools he supplied.' },
    { chapters: [
      { chapterNumber: 41, title: 'Anyaman Jembatan Bergeser', paragraphs: ['Danu melihat anyaman pagar jembatan bergeser tiga ruas setelah gerobak kru Bagas melintas malam hari. Sambungan bawah retak, meski mandor memerintahkan warga tetap memakai jalur itu. Vina mengikat serat merah pada tiap silang bambu untuk membaca perubahan beban. Jembatan tersebut menjadi satu-satunya jalan antara rumah mereka dan dusun tempat Danu merawat seorang penanam sakit.'] },
      { chapterNumber: 42, title: 'Keranjang Menguji Bentang', paragraphs: ['Karsa menggantung keranjang batu pada bentang tengah, lalu Vina mencatat silang mana yang turun lebih dahulu. Uji ketiga membuat satu ikatan putus dan batu jatuh ke jurang. Danu meminta jembatan ditutup, tetapi warga seberang belum memiliki persediaan obat. Mereka sepakat membatasi lintasan sambil menyiapkan cara mengirim barang tanpa membawa tubuh melintasi retakan.'] },
      { chapterNumber: 43, title: 'Tali Meluncurkan Obat', paragraphs: ['Danu memasang tali miring dan mengirim bungkusan obat dalam keranjang kecil ke dusun seberang. Percobaan pertama tersangkut di tengah, lalu Vina menambahkan roda kayu buatan Karsa. Bungkusan berikutnya tiba utuh. Jalur sederhana itu belum mengangkut manusia, tetapi memberi mereka kemungkinan memutus jembatan tanpa meninggalkan keluarga sakit sepenuhnya terasing.'] },
      { chapterNumber: 44, title: 'Jejak Lumpur pada Bilah', paragraphs: ['Serat merah bergeser lagi setelah malam tanpa warga melintas. Lumpur pada pagar memuat sekam gudang kantor, menunjukkan gerobak Bagas masih memakai jembatan diam-diam. Vina ingin menangkap rombongan berikutnya, sedangkan Danu menolak menjadikan retakan sebagai perangkap. Mereka memasang lonceng pada pangkal dan mulai memindahkan warga seberang sebelum mencari siapa yang membawa muatan.'] },
      { chapterNumber: 45, title: 'Nenek Terakhir Menyeberang', paragraphs: ['Warga mengantar seorang nenek melewati bentang dengan tali pinggang sebelum hujan turun. Danu tetap di dusun seberang untuk menjaga penanam sakit dan berkata Vina tidak boleh memotong jembatan selagi ia di sana. Vina berjanji menunggu isyarat kain putih dari bukit. Janji itu membatasi tindakannya ketika tiap bunyi bambu menandakan keruntuhan makin dekat.'] },
      { chapterNumber: 46, title: 'Gerobak Datang Saat Hujan', paragraphs: ['Lonceng pangkal berbunyi ketika gerobak kantor membawa peti melaju dalam hujan. Vina dan warga menghadang, tetapi kru memukul kendali dan terus maju. Dua silang bambu patah di belakang roda pertama. Dari seberang, Danu mengangkat kain putih karena pasien telah aman, lalu berteriak agar kakaknya menyelamatkan orang, bukan mempertahankan bentang yang sudah gagal.'] },
      { chapterNumber: 47, title: 'Bentang Tengah Diputus', paragraphs: ['Setelah kru berlari kembali ke sisi kantor, Vina mengayunkan parang pada ikatan utama. Karsa memotong tali kedua dan bentang tengah jatuh bersama gerobak kosong ke dasar jurang. Peti tertahan di sisi atas, tetapi Danu terpisah dari rumah tanpa jalan pulang. Keputusan itu menghentikan lintasan Bagas sekaligus mengubah kehidupan kedua dusun untuk berbulan-bulan.'] },
      { chapterNumber: 48, title: 'Danu Tinggal di Seberang', paragraphs: ['Danu tidur di rumah penanam yang telah pulih dan berbicara dengan Vina melalui jurang saat udara cerah. Ia mengaku marah karena janji pulang mereka hilang bersama jembatan, meski pemotongan tadi menyelamatkan kru. Vina tidak meminta pengampunan cepat. Mereka menyusun giliran keranjang agar makanan, surat, dan obat tetap bergerak sementara bentang baru dirancang.'] },
      { chapterNumber: 49, title: 'Kabel Pertama Direntangkan', paragraphs: ['Karsa merentangkan kabel bekas pengangkut teh di antara dua pangkal, dibantu warga dari kedua sisi. Keranjang besar dapat membawa beras dan alat, tetapi belum aman untuk manusia. Danu mengirim baju kerja Vina yang tertinggal di rumahnya sebagai tanda ia masih menjaga hubungan mereka. Vina membalas dengan bibit cabai dan pesan tanpa janji tanggal kepulangan.'] },
      { chapterNumber: 50, title: 'Dua Ujung dalam Kabut', paragraphs: ['Kecamatan menyita peti kantor yang tertahan dan melarang jembatan dibuka kembali sebelum dibangun ulang. Bagas kehilangan jalur malam, namun dusun tetap terbelah. Vina memutar roda kabel saat keranjang pertama berisi hasil kebun melintas di atas jurang. Dalam kabut, dua ujung jembatan lama bergantung tanpa bertemu, sementara suara Danu terdengar dari sisi lain.'] },
    ], justification: 'The ending turns measured bridge failure into an irreversible demolition that stops Bagas while separating Vina and Danu, then shows a limited material connection rather than instant repair.' },
    { chapters: [
      { chapterNumber: 41, title: 'Lonceng Tanah Bergetar', paragraphs: ['Lonceng tanah di rumah jaga bergetar tanpa angin ketika kendaraan berat kantor melintas di jalan atas. Vina menemukan retak rambut pada dinding sumur warga dan menempelkan empat bilah daun lontar sebagai pengukur. Bu Ningsih mencatat jaraknya. Mereka menduga getaran baru sedang merusak rongga air yang menopang teras bawah.'] },
      { chapterNumber: 42, title: 'Daun Lontar Bergeser', paragraphs: ['Dua bilah lontar bergeser selebar kuku sesudah truk kedua lewat. Vina mengukur retak bersama Mbah Ripto, lalu memindahkan tempayan dari sisi dinding yang melemah. Bagas menyebut perubahan itu akibat kemarau. Vina menolak menutup sumur sebelum keluarga lereng memperoleh tempat mengambil air lain yang dapat dijangkau anak-anak.'] },
      { chapterNumber: 43, title: 'Rongga Bernapas Dingin', paragraphs: ['Karsa menurunkan lampu minyak ke sumur dan nyalanya condong menuju celah batu, menandakan udara bergerak dari rongga bawah jalan. Vina memasukkan serbuk kunyit ke rembesan; warna kuning muncul dekat tiang kantor. Bukti tersebut menghubungkan retakan dengan jalur kendaraan, tetapi menghentikan truk berarti memutus angkutan teh tempat Danu bekerja.'] },
      { chapterNumber: 44, title: 'Jalan Ringan Diuji', paragraphs: ['Warga menguji jalur kebun lama memakai dua keranjang teh dan papan pada bagian berlumpur. Satu papan patah, membuat muatan tumpah, tetapi orang dapat lewat tanpa mendekati sumur. Danu menghitung perjalanan akan bertambah satu jam. Vina meminta percobaan kedua sebelum mengusulkan agar truk dilarang melewati ruas dekat sumur.'] },
      { chapterNumber: 45, title: 'Bagas Menambah Muatan', paragraphs: ['Bagas justru mengirim truk dengan muatan ganda dan menyatakan panen tidak boleh menunggu ketakutan warga. Getarannya menjatuhkan batu dari bibir sumur dan membuat air keruh. Danu kehilangan giliran kerja setelah menolak naik. Ia menyalahkan Vina karena keputusan itu mengancam penghasilan mereka, lalu pergi bermalam di rumah Karsa.'] },
      { chapterNumber: 46, title: 'Tiang Kantor Mulai Miring', paragraphs: ['Hujan singkat melunakkan tanah dan tiang penanda kantor miring ke arah rongga. Bu Ningsih menutup jalan atas memakai bangku sekolah, sementara warga memindahkan air dengan kendi. Vina menyusun catatan getaran, warna kunyit, dan posisi tiang. Bagas mengancam mengambil bangku, tetapi pengemudinya sendiri menolak menyeberangi retakan.'] },
      { chapterNumber: 47, title: 'Jalan Atas Diputus', paragraphs: ['Retakan membelah jalan ketika truk kosong mencoba berbalik. Vina memerintahkan Karsa mencabut dua papan jembatan kecil sehingga kendaraan lain tidak dapat mendekat. Tindakan itu juga menutup rute tercepat menuju pasar. Danu membantu pengemudi turun, namun mengatakan ia belum memaafkan Vina karena memilih keselamatan seluruh lereng tanpa berbicara dengannya.'] },
      { chapterNumber: 48, title: 'Keranjang Menempuh Kebun', paragraphs: ['Panen teh pertama dibawa melalui jalur kebun dengan keranjang kecil bergilir. Perjalanan lambat dan sebagian daun rusak terkena hujan, tetapi tanah dekat sumur berhenti bergerak. Vina menyerahkan upah angkutnya kepada Danu yang kehilangan pekerjaan. Danu menolak uang itu, lalu ikut memperkuat papan jalur tanpa menganggap pertengkaran mereka selesai.'] },
      { chapterNumber: 49, title: 'Air Jernih Kembali', paragraphs: ['Serbuk kunyit tidak lagi muncul di sisi kantor dan air sumur perlahan jernih. Di bibir sumur, Vina mengakui kepada Danu bahwa ia memakai ketakutan kehilangan warga untuk mengabaikan hak kakaknya ikut memutuskan. Danu mengakui penghasilannya membuat ia menutup mata pada retakan. Mereka sepakat bekerja bersama tanpa menjanjikan luka itu segera hilang.'] },
      { chapterNumber: 50, title: 'Jalur Kecil Menjadi Tetap', paragraphs: ['Kecamatan menutup ruas dekat sumur bagi truk dan menetapkan jalur kebun sebagai rute angkut ringan. Bagas kehilangan kecepatan pengiriman, sementara keluarga lereng tetap harus bergiliran membawa teh. Vina dan Danu memasang lonceng tanah di gerobak pertama. Sumur bertahan, tetapi tambahan perjalanan menjadi harga harian yang dibayar seluruh lembah.'] },
    ], justification: 'The ending turns measured vibration into a permanent heavy-vehicle ban, preserves the shared well at a durable transport cost, and resolves the sibling conflict without erasing it.' },
    { chapters: [
      { chapterNumber: 41, title: 'Hujan Es Merobek Atap', paragraphs: ['Hujan es merobek tiga atap bambu dan melukai seorang penanam yang berlari mencari perlindungan. Ramalan radio menyebut badai kedua akan tiba dalam sembilan hari. Bagas mengunci bangunan kantor, sementara lumbung keluarga Vina menjadi satu-satunya ruang dengan balok utuh. Vina membuka pintunya, tetapi lantai sempit tidak mungkin menampung seluruh warga lereng.'] },
      { chapterNumber: 42, title: 'Keranjang Menguji Balok', paragraphs: ['Pada setiap balok, Karsa menggantung bakul berisi batu untuk menguji beban. Satu sambungan berderit sebelum berat setara empat orang tercapai. Mbah Ripto menghitung warga yang sulit berjalan, sedangkan Vina mengukur ruang di antara rak keluarga. Agar lumbung aman, rak penyimpanan harus dibongkar dan kayunya dijadikan penyangga, mengakhiri fungsi yang diwariskan ayahnya.'] },
      { chapterNumber: 43, title: 'Mbah Menolak Tempat Dalam', paragraphs: ['Mbah Ripto menolak tempat dekat pintu karena seorang ibu dengan bayi lebih membutuhkannya. Vina menyusun urutan masuk berdasarkan kemampuan bergerak, bukan kegunaan seseorang saat bekerja. Lelaki tua itu menuduhnya mengasihani usia. Pertengkaran mereka membuat jelas bahwa perlindungan bersama akan gagal bila warga merasa keselamatan harus dibayar dengan menyerahkan martabat.'] },
      { chapterNumber: 44, title: 'Pintu Darurat Dicoba', paragraphs: ['Karsa membuka pintu darurat pada dinding belakang dan warga mencoba keluar tanpa membawa barang. Rak-rak membuat dua jalur menyempit, sementara peti keluarga Vina menghalangi belokan terakhir. Danu meminta peti itu dipindahkan. Vina menolak karena isinya pakaian ibu mereka, lalu menyadari ia sedang mempertahankan kenangan dengan ruang yang mungkin dibutuhkan tubuh hidup.'] },
      { chapterNumber: 45, title: 'Gudang Kantor Tetap Dikunci', paragraphs: ['Para ibu meminta Bagas membuka gudang teh sebagai tempat kedua, tetapi ia menuntut surat pelepasan tuntutan air. Mereka pulang tanpa kesepakatan. Vina menawarkan lumbung lagi, kali ini dengan syarat setiap keluarga hanya membawa satu bungkusan. Mbah Ripto bersedia membantu latihan masuk bila ia boleh memilih sendiri tempat duduk dan tugasnya selama badai.'] },
      { chapterNumber: 46, title: 'Latihan Pertama Gagal', paragraphs: ['Latihan masuk berubah kacau ketika anak-anak mencari orang tua dan warga berebut sudut kering. Mbah Ripto memukul lesung dengan pola berbeda untuk tiap kelompok, membuat arus manusia terpisah tanpa teriakan. Uji ulang selesai lebih cepat, namun rak timur bergoyang saat semua orang duduk. Karsa berkata penyangga tambahan tidak dapat dipasang tanpa menggergaji dudukan permanennya.'] },
      { chapterNumber: 47, title: 'Peti Ibu Dibuka', paragraphs: ['Vina membuka peti ibu bersama Danu dan membagi pakaian di dalamnya kepada keluarga yang atapnya rusak. Mereka menyimpan satu selendang, lalu memakai papan peti untuk memperkuat pintu darurat. Tindakan itu membebaskan ruang, tetapi balok utama masih membutuhkan kayu rak. Di luar, awan es menutup puncak sehari lebih cepat dari ramalan radio.'] },
      { chapterNumber: 48, title: 'Rak Warisan Digergaji', paragraphs: ['Vina menggergaji dudukan rak yang menyatu dengan dinding lumbung. Karsa memasang kayunya sebagai penyangga silang, sementara Mbah Ripto mengatur warga masuk menurut bunyi lesung. Badai menghantam sebelum papan terakhir terpasang. Semua orang berlindung, tetapi karung keluarga Vina yang tak lagi memiliki rak basah ketika air merembes sepanjang lantai.'] },
      { chapterNumber: 49, title: 'Caping pada Bekas Rak', paragraphs: ['Pagi sesudah badai, rumah-rumah masih berdiri meski banyak atap berlubang. Warga menggantung caping pada bekas rak dan membagi bahan makanan yang selamat. Mbah Ripto memilih tetap dekat pintu untuk menyambut keluarga terakhir, bukan karena diperintah Vina. Lumbung tidak dapat kembali menjadi gudang privat, dan hasil panen kini harus disimpan tersebar di beberapa rumah.'] },
      { chapterNumber: 50, title: 'Cahaya Masuk dari Dinding', paragraphs: ['Desa menetapkan lumbung sebagai tempat berlindung tetap dan membangun rak kecil pada rumah-rumah untuk mengganti penyimpanan lama. Bagas belum membuka gudang kantor, sehingga tuntutan terhadapnya berlanjut. Vina menjemur karung basah bersama Danu. Cahaya pagi masuk melalui celah dudukan papan keluarga, menerangi caping berbagai ukuran yang tertinggal setelah warga pulang.'] },
    ], justification: 'The ending forces Vina to dismantle her inherited private storehouse so it can shelter the village, while Mbah Ripto retains agency and storage loss remains unresolved.' },
  ],
  WEAK: [
    { chapters: [
      { chapterNumber: 41, title: 'Kabut Menutup Papan Nama', paragraphs: ['Kabut pagi menempel pada papan nama simpang sampai huruf-hurufnya tampak seperti bayang. Vina mengusap permukaan kayu dengan kain basah, lalu menyeka sisa air dengan lengan bajunya. Ia turun dari bangku kayu dan memeriksa tulisan dari kejauhan, memastikan setiap huruf terbaca lagi. Seorang pengendara sepeda berhenti menanyakan arah ke balai desa. Vina menunjuk jalan setapak di belakang warung, kemudian membawa bangku masuk ke rumah. Menjelang siang papan itu kering dan lumpur dari sepatunya sudah bersih dari anak tangga.'] },
      { chapterNumber: 42, title: 'Pagar Kebun Dicat', paragraphs: ['Karsa mengaduk sisa kapur putih dalam kaleng kecil sebelum menyapukan kuas pada bilah pagar bengkelnya. Vina datang membawa air minum dan membantu memegang kaleng sambil menahan bilah yang longgar. Mereka membicarakan kucing Karsa yang suka tidur di tumpukan karung. Setelah sebelas bilah selesai, Karsa mencuci kuas di parit dan menggantungnya pada paku. Vina meminum air yang tersisa, mengembalikan cangkir ke dapur, lalu berjalan pulang ketika lengking bel sepeda motor terdengar dari tikungan.'] },
      { chapterNumber: 43, title: 'Keranjang Dicuci Hujan', paragraphs: ['Danu meninggalkan keranjang panen di halaman saat hujan sore turun mendadak. Vina mengangkat keranjang ke serambi, membaliknya untuk mengalirkan air, dan menggosok lumpur dengan sabut kelapa. Satu ikatan rotan di bagian bawah sudah longgar, jadi ia menjepitnya dengan anyaman baru sambil menekan anyaman lain agar tetap rapat. Setelah kering di bawah matahari senja, keranjang itu kembali diletakkan di dekat pintu. Danu berterima kasih singkat sambil mengunyah pisang, lalu masuk kamar. Vina menutup pintu dan mematikan lampu teras lebih awal dari biasanya.'] },
      { chapterNumber: 44, title: 'Kapur Kelas Ditambah', paragraphs: ['Sebuah kotak kapur baru tiba di sekolah lewat kurir kecamatan, dan Bu Ningsih membukanya di meja kelas. Vina memisahkan kapur putih dari kapur warna, menyusunnya pada rak kayu sesuai panjang batang. Murid-murid berebut memegang kapur biru untuk menggambar gunung di sudut papan, sementara yang lain menebalkan garis dengan kapur kuning. Bu Ningsih mengepel sisa debu kapur di lantai. Vina membawa kotak kosong ke rumah jaga dan meletakkannya di tumpukan kertas bekas. Bel istirahat berbunyi, dan anak-anak berlari ke halaman.'] },
      { chapterNumber: 45, title: 'Pasar Pindah Sehari', paragraphs: ['Lapangan pasar dipakai rapat kecamatan pada hari Sabtu, sehingga jadwal pasar mingguan dipindah ke Kamis pagi. Vina bangun lebih awal, membawa dua keranjang belanja, dan berjalan menyusuri jalan setapak menuju tenda sayur. Ia membeli garam bata, minyak kelapa, dan empat ikat kangkung. Di warung sebelah, Bagas duduk memeriksa nota, tetapi ia tidak menoleh ketika Vina lewat. Vina membayar dengan uang receh dan pulang sebelum matahari naik. Ibu-ibu lain baru mulai berdatangan saat ia sudah meletakkan belanjaan di meja dapur.'] },
      { chapterNumber: 46, title: 'Atap Bengkel Ditambal', paragraphs: ['Danu membawa dua lembar seng bekas ke bengkel Karsa setelah hujan pertama merembes melalui atap. Mereka menaiki tangga bambu dan memasang seng pada lubang dekat dinding, menekan paku baru ke tepi yang melengkung. Vina datang membawa termos air dan menghitung sisa paku dalam kaleng sambil duduk di tepi pintu. Karsa menguji tambalan dengan menuangkan semangkuk air ke atas seng; air mengalir ke parit tanpa menetes ke dalam. Mereka turun saat langit memerah. Vina meninggalkan termos kosong di bangku kerja.'] },
      { chapterNumber: 47, title: 'Buku Sekolah Disampul', paragraphs: ['Bu Ningsih membagikan kertas cokelat dan lem kanji kepada murid untuk menyampul buku pelajaran. Vina membantu menulis nama murid pada sudut kanan sampul dengan pensil, sementara anak-anak merapikan lipatan di meja. Satu sampul sobek ketika tergesa ditarik, lalu mereka menempelkan kertas baru. Menjelang petang, tumpukan buku tersusun menurut kelas di rak dekat jendela. Vina membersihkan lem dari jarinya dengan minyak kelapa. Bu Ningsih menyalakan lampu dan menyuruh anak-anak pulang sambil membawa dua buku yang masih basah.'] },
      { chapterNumber: 48, title: 'Pemeriksa Tiba Mendadak', paragraphs: ['Pagi hari dua mobil dinas berhenti di depan kantor, dan tiga orang berseragam turun membawa map tebal. Mereka meminta Bagas membuka lemari dokumen, lalu memindahkan berkas ke dalam peti kayu. Warga berkerumun di seberang jalan, sebagian mengintip dari balik tiang. Vina berdiri di dekat sumur, mengamati peti itu dimuat ke bagasi mobil. Tidak ada yang memanggilnya atau menanyakan catatan apa pun kepadanya. Sesudah mobil pergi, debu mengendap dan warga membicarakan audit kota sambil kembali ke meja dagangannya.'] },
      { chapterNumber: 49, title: 'Makan Malam Tetap Biasa', paragraphs: ['Vina menanak ubi di atas tungku dan mengupas dua buah pisang untuk makan malam. Danu pulang ketika langit sudah gelap, mencuci tangan di ember, lalu duduk di tikar tanpa melepas baju kerjanya. Mereka membicarakan harga sabun yang naik dan jadwal pengiriman teh pekan depan. Kabar bahwa Bagas mungkin dipindahkan terdengar dari tukang sayur, tetapi tidak seorang pun mengangkat topik itu lebih jauh. Setelah piring kosong, Danu menguap dan masuk ke kamar. Vina mematikan lampu dan menyapu sisa kulit pisang ke lubang sampah.'] },
      { chapterNumber: 50, title: 'Surat Pemindahan Dibaca', paragraphs: ['Surat beramplop cokelat dipaku di papan pengumuman dekat gerbang, menyatakan Bagas dipindahkan ke kecamatan tetangga dan jatah air sebagian dibuka kembali. Vina membaca surat itu sambil berdiri di antara warga lain yang antre membeli garam. Ketika ia tiba di rumah, ia menjemur pakaian basah di tali sepanjang teras. Danu membawa pulang satu karung teh, meletakkannya di sudut, dan bertanya apakah mereka ikut merayakan. Vina menggeleng dan menutup jendela karena angin mulai membawa kabut. Truk kantor terlihat keluar dari halaman menjelang sore.'] },
    ], justification: 'The runway consists of unrelated chores, while an external inspection resolves the conflict without using any prepared action, relationship, or cost.' },
    { chapters: [
      { chapterNumber: 41, title: 'Kebun Bunga Direncanakan', paragraphs: ['Bu Ningsih membentangkan kertas bekas di meja kelas dan menggambar empat petak persegi di halaman sekolah. Vina meminjam pensilnya untuk mempertegas garis, lalu menambahkan lingkaran kecil sebagai tempat bunga berdiri. Mereka menghitung kebutuhan bambu dari tumpukan di belakang dapur, dan Vina mencatat angkanya di tepi kertas dengan arang. Murid-murid mengintip dari luar jendela sambil menebak warna kelopak yang akan ditanam. Bu Ningsih menyimpan kertas itu di lemari kapur, mengingatkan Vina untuk membawa cangkul kecil pada akhir pekan.'] },
      { chapterNumber: 42, title: 'Bambu Petak Dipotong', paragraphs: ['Karsa membawa enam belas bilah bambu tua ke halaman sekolah dan memotongnya sama panjang dengan golok. Murid-murid mengampelas ujung bilah dengan batu sungai sampai halus, lalu menumpuknya di bawah pohon. Vina menghitung bilah satu per satu sambil menyebut angka yang sudah dipotong pada catatan arangnya. Beberapa murid berlomba mengangkat bilah dalam kelompok dua orang. Menjelang sore, seluruh bilah berdiri di tanah lembap dan diikat silang dengan tali ijuk. Karsa memungut serpihan bambu dan membawanya pulang untuk kayu bakar.'] },
      { chapterNumber: 43, title: 'Benih Bunga Tiba', paragraphs: ['Kurir menurunkan lima amplop cokelat berisi benih bunga di ruang guru, lengkap dengan gambar kelopak pada sampulnya. Bu Ningsih membuka satu amplop dan menuangkan biji ke telapak tangannya, memeriksa warna kulit biji itu satu per satu. Vina menulis nama kelompok murid pada setiap amplop dengan kapur, lalu mengikatnya dengan karet. Satu amplop disimpan di rak lemari sebagai cadangan, bersama kotak kapur dan kertas bekas. Murid-murid mencium amplop bergambar merah jambu dan bertanya kapan biji mulai ditanam. Vina menjawab setelah tanah digemburkan.'] },
      { chapterNumber: 44, title: 'Tanah Sekolah Digemburkan', paragraphs: ['Danu mencangkul tanah di samping sekolah seusai giliran kerjanya di kebun teh, membalik gumpalan tanah dan memecahnya dengan punggung cangkul. Vina mengikuti dari belakang dengan penggaruk, meratakan petak yang sudah dibalik. Mereka berbincang tentang warna bunga kesukaan ibu mereka, kuning untuk bunga kenikir dan ungu untuk aster. Percakapan itu terputus ketika mesin truk lewat di jalan atas dan Danu menoleh ke arah suara. Ia melanjutkan mencangkul tanpa berkomentar, dan Vina mengumpulkan akar rumput ke dalam keranjang. Tanah petak terakhir selesai dijelang senja.'] },
      { chapterNumber: 45, title: 'Hujan Merusak Dua Petak', paragraphs: ['Hujan sore mengguyur halaman sekolah dan dua petak yang belum ditanami berubah menjadi kubangan. Vina datang keesokan paginya dengan sendok bata, memindahkan tanah yang tergenang ke petak yang lebih tinggi. Murid-murid membantu memperkuat batas bambu dengan mengikat bilah yang miring menggunakan serat kelapa. Bu Ningsih menyebut pekerjaan ulang itu sebagai latihan menyambung tali bagi murid-muridnya. Lumpur mengering menjelang siang, dan permukaan tanah kembali rata seperti sebelumnya. Vina menahan bilah bambu dengan tumitnya sambil mengencangkan ikatan.'] },
      { chapterNumber: 46, title: 'Benih Ditanam Bergilir', paragraphs: ['Tiap kelompok murid mendapat satu baris petak dan menanam biji dengan jarak dua jari, menekan tanah di atasnya dengan ibu jari. Vina berjalan di antara baris sambil membawa kendi air, menyiram setiap lubang dengan satu gayung. Selesai menanam, kelompok memasang papan nama kayu bertuliskan warna kelopak yang mereka pilih. Bu Ningsih meminta murid mencatat tanggal tanam pada dinding kelas. Sore itu halaman bau tanah basah dan sebagian biji terlihat seperti butiran pasir di permukaan. Vina membawa kendi kosong kembali ke rumah.'] },
      { chapterNumber: 47, title: 'Pagar Petak Selesai', paragraphs: ['Pagar kayu mengelilingi empat petak selesai setelah murid mengikat bilah terakhir pada tiang sudut. Anak-anak menggantung daun kering dan kuntum ilalang pada sela pagar sebagai hiasan. Karsa memeriksa sambungan, menemukan satu ikatan longgar di sisi barat, dan menggantinya dengan tali ijuk baru. Vina menyapu serutan kayu dari halaman dan menumpuknya di belakang tungku sekolah. Bu Ningsih memotret halaman dengan kamera saku, lalu menyimpan foto itu di lemari kelas bersama buku bersampul cokelat. Murid-murid berlari mengelilingi pagar ketika bel pulang berbunyi.'] },
      { chapterNumber: 48, title: 'Bagas Dicopot Kecamatan', paragraphs: ['Surat resmi bergaris atas nama kecamatan direkatkan di papan gerbang, menyebutkan Bagas dicopot dari jabatan mandor setelah audit di kota selesai. Warga berkumpul di depan sekolah membaca pengumuman itu dua kali, sebagian mengangguk dan sebagian menggeleng. Vina membaca seluruh isinya tanpa menemukan nama siapa pun dari lereng sebagai saksi. Ia melipat ujung surat yang terangkat angin dan kembali ke kelas membawa kendi kosong. Bu Ningsih menunda pelajaran menggambar selama sepuluh menit karena anak-anak terus bertanya tentang mobil dinas yang terparkir di kantor.'] },
      { chapterNumber: 49, title: 'Tunas Pertama Terlihat', paragraphs: ['Tunas hijau pucat muncul dari petak paling dekat kelas, tingginya kurang dari satu ruas jari. Bu Ningsih mengeluarkan penggaris kayu dan meminta murid mengukur tunas itu dari pangkal sampai ujung daun. Vina menulis angka pada papan kecil yang disandarkan di dekat petak, lalu membandingkannya dengan catatan tanggal tanam. Kuntum kedua menyembul dari baris tengah saat Vina menyiram. Danu melewati halaman memikul dua keranjang teh dan berhenti sebentar untuk melihat, tersenyum ketika daun pertama membuka. Ia melanjutkan langkah tanpa berkata apa-apa.'] },
      { chapterNumber: 50, title: 'Bunga Mekar di Halaman', paragraphs: ['Kelopak merah jambu dan kuning mekar memenuhi empat petak ketika pejabat baru menandatangani pembukaan jatah air penuh di gerbang. Murid-murid berfoto di depan pagar dengan bunga di tangan mereka. Vina membagikan sisa benih cadangan kepada tiga ibu yang menanam di pekarangan rumah. Danu membawa teh, dan Bu Ningsih mencatat nama ibu-ibu itu di buku kelas. Beberapa bunga mulai mengering di bawah matahari siang. Vina menyiram petak dekat pintu, lalu duduk di bangku sambil memperhatikan gerbang air yang berkilau di kejauhan.'] },
    ], justification: 'A safe flower-garden project occupies the runway while an unseen audit removes the antagonist, leaving the central dramatic question unanswered by the authored actions.' },
    { chapters: [
      { chapterNumber: 41, title: 'Kain Jemur Dikumpulkan', paragraphs: ['Angin membawa tanda hujan menjelang sore, dan Vina bergegas mengumpulkan kain jemur dari tali di halaman. Ia menemukan satu noda tanah pada ujung selendang biru, lalu mencuci noda itu di ember memakai sabut dan sedikit abu. Setelah dibilas dua kali, selendang diperas dan digantung pada kayu dekat tungku. Vina melipat kain lain yang sudah kering dan menyimpannya di peti kayu dekat tempat tidur. Ibu dari rumah tetangga menyapa dari balik pagar, menanyakan apakah hujan sudah mulai turun di lereng atas. Vina menjawab belum.'] },
      { chapterNumber: 42, title: 'Tempayan Dipindah Teduh', paragraphs: ['Danu menggeser tempayan air dari halaman depan ke sisi rumah yang teduh di bawah pohon aren. Vina membantu mengganjal dasar tempayan dengan tiga batu pipih agar tidak miring. Mereka mengisi tempayan sampai penuh memakai ember bergantian, lalu mengamati permukaan air selama beberapa saat untuk memastikan tidak rembes. Danu menutup mulut tempayan dengan anyaman bambu dan mengingatkan Vina memakai air dari sisi selatan lebih dulu. Sore itu dua ekor ayam minum dari ceceran di bawah tempayan. Vina mengusirnya dengan sapu lidi.'] },
      { chapterNumber: 43, title: 'Daun Teh Dipilah', paragraphs: ['Vina duduk di serambi memilah daun teh rusak dari keranjang Danu, membuang daun berlubang ke dalam ember kompos. Daun yang masih utuh ia susun di atas anyaman agar tidak lembap. Danu datang dari arah kebun dan menyebut mandor sedang sibuk dengan truk baru, lalu masuk untuk minum. Vina melanjutkan memilah sampai keranjang berisi daun bersih, mengikatnya dengan tali, dan menaruhnya di dekat pintu. Seekor capung hinggap di tepi keranjang, dan Vina membiarkannya sampai petang. Ia menyapu daun rusak ke lubang kompos lalu mencuci tangan.'] },
      { chapterNumber: 44, title: 'Jalan Setapak Disapu', paragraphs: ['Angin malam membawa daun kering ke jalan setapak depan sekolah, dan Bu Ningsih mengajak murid menyapu sebelum pelajaran dimulai. Vina membantu mengumpulkan tiga tumpukan daun dengan penggaruk bambu, sementara anak-anak mengangkat tumpukan itu ke dalam karung. Mereka menemukan satu sandal putus di parit dan menaruhnya di pagar untuk diambil pemiliknya. Jalan tampak bersih menjelang bel pertama. Bu Ningsih memuji murid yang menyapu paling cepat, lalu membuka pintu kelas. Vina menyimpan penggaruk di belakang dapur sekolah dan membasuh kakinya di kolam.'] },
      { chapterNumber: 45, title: 'Kucing Tidur di Serambi', paragraphs: ['Seekor kucing belang tidur di serambi rumah jaga dari pagi sampai sore, mengikuti gerak bayangan pagar yang bergeser. Vina meletakkan nasi sisa di daun pisang di dekatnya, dan kucing itu bangun, mengendus, lalu makan dengan lahap. Mbah Ripto duduk di kursi rotan sambil mengamati kucing itu menjilati kaki belakangnya, sesekali tertawa kecil ketika kucing itu tergelincir di tikar licin. Setelah makan, kucing itu kembali tidur dalam posisi melingkar. Vina mengambil daun pisang kosong dan membuangnya ke lubang sampah di belakang dapur.'] },
      { chapterNumber: 46, title: 'Panci Ditambal Karsa', paragraphs: ['Karsa membawa panci Vina yang bocor ke bengkel dan memotong keping logam seukuran ibu jari. Ia meletakkan keping itu di atas lubang, menekannya dengan palu kecil, lalu mematri tepinya dengan timah panas. Untuk menguji, ia menuangkan segelas air ke dalam panci dan membaliknya; air tidak menetes sedikit pun. Vina datang membawa dua ikat sayur sebagai ganti dan meletakkannya di bangku kerja. Karsa menggosok panci dengan sabut sampai mengilap, lalu menyerahkannya. Vina menaruh panci di rak dapur dan menggantung sayur di dekat tungku.'] },
      { chapterNumber: 47, title: 'Kabut Turun Lebih Awal', paragraphs: ['Kabut turun dari punggung lereng sebelum senja, menutupi rumah-rumah sampai hanya atap yang terlihat. Warga menutup jendela dan memasang palang kayu pada pintu agar angin tidak masuk. Vina menyalakan lampu minyak lebih awal dan menunggu Danu pulang dari kebun. Ketika kakaknya tiba dengan sepatu berlumpur, mereka duduk di ruang tengah minum teh panas menunggu kabut mengental. Suara kentongan dari balai terdengar dua kali, lalu berhenti. Danu menguap dan merebahkan diri di tikar. Vina mematikan lampu teras dan mengunci pintu.'] },
      { chapterNumber: 48, title: 'Kabar Audit dari Kota', paragraphs: ['Pedagang sayur membawa kabar bahwa kantor Bagas sedang diperiksa oleh tim dari kota. Ia mendengar kabar itu dari pengemudi truk yang menurunkan karung di pasar pagi. Vina menerima kabar saat membeli cabai dan bertanya apa yang diperiksa, tetapi pedagang hanya mengangkat bahu. Sepanjang jalan pulang ia melihat dua mobil dinas terparkir di dekat kantor. Ia menaruh cabai di dapur dan tidak mengunjungi kantor. Danu pulang lebih malam membawa kabar yang sama dari teman kerjanya. Mereka makan malam tanpa membahasnya lebih jauh.'] },
      { chapterNumber: 49, title: 'Lampu Dapur Dipadamkan', paragraphs: ['Malam itu Vina dan Danu makan bubur jagung dalam diam, hanya terdengar sendok menyentuh mangkuk. Danu menyebut bahwa pemeriksaan kantor mungkin selesai besok, lalu menguap dan meletakkan mangkuk di wastafel. Vina membersihkan tungku, menutup periuk, dan memadamkan lampu dapur. Kabut menerpa jendela pelan-pelan. Vina mengatur tikar tidur dan menggulung selimut Danu yang terlipat di sudut. Suara jangkrik memenuhi halaman sampai api tungku padam seluruhnya. Vina membuka jendela sebentar, melihat kabut menebal, lalu menutupnya kembali.'] },
      { chapterNumber: 50, title: 'Bagas Pergi dengan Truk', paragraphs: ['Pagi harinya truk kantor terparkir di depan rumah Bagas, dan koper serta karung dimuat ke bak truk oleh dua pekerja kebun. Bagas menutup pintu rumahnya, menyerahkan kunci kepada seorang petugas, lalu naik ke kabin. Warga memandang dari balik pagar sambil menyapu halaman atau menimba air. Vina menyapu serambi dan memberi makan kucing belang yang datang kembali. Ketika truk berputar di depan gerbang, Bagas tidak menoleh ke arah rumah Vina. Sesudah truk hilang di tikungan, jalan kembali sepi dan burung pipit turun ke tanah.'] },
    ], justification: 'Domestic observations repeat without causal accumulation, and the antagonist exits through an external audit that none of the runway material prepares.' },
    { chapters: [
      { chapterNumber: 41, title: 'Toples Garam Diberi Label', paragraphs: ['Vina menulis huruf besar pada tiga lembar kertas bekas, memakai arang yang dipertajam dengan pisau kecil. Ia menempelkan label pada toples garam, gula, dan tepung dengan lem kanji, lalu menyusunnya di rak dapur menurut tinggi. Sebelum menaruh toples terakhir, ia mengusap debu dari permukaan kaca dengan kain. Danu melihat susunan baru itu dan mencoba membuka tutup toples garam, meletakkannya kembali tanpa berkata. Vina mengelap sisa lem pada jarinya. Dapur tampak rapi sampai senja, dan lampu dapur menyala ketika hujan mulai turun di atap.'] },
      { chapterNumber: 42, title: 'Rak Bumbu Dibersihkan', paragraphs: ['Jelaga menebal pada rak bumbu di dapur, dan Vina menurunkannya satu per satu ke lantai. Ia menyeka papan rak dengan air panas campur abu, sementara Danu memindahkan piring bersih ke meja. Botol kosong berisi sisa kunyit dan kemiri dibuang ke lubang sampah. Setelah papan kering, Vina menyusun kembali botol menurut ukuran dan menaruh daun salam di bagian sudut untuk mengusir serangga. Danu menggantung dua kain lap baru pada paku di dinding. Mereka makan siang dengan meja yang lebih terang dari biasan lampu sore.'] },
      { chapterNumber: 43, title: 'Kayu Bakar Ditumpuk', paragraphs: ['Karsa mengirim satu gerobak kayu bakar dan menurunkannya di samping tungku dapur Vina. Vina menumpuk batang kayu menurut panjangnya, yang pendek di dekat lubang tungku dan yang panjang berdiri di dinding. Danu ikut mengangkat dua batang terbesar sambil mengeluh punggungnya pegal. Mereka mengikat tumpukan dengan tali ijuk supaya tidak roboh ketika angin kencang. Sisa serpihan kulit kayu disapu ke parit belakang. Karsa minum air di serambi sebelum menarik gerobak kosong pulang. Menjelang malam, tumpukan kayu itu sudah setinggi pinggang Vina.'] },
      { chapterNumber: 44, title: 'Sendok Kayu Diganti', paragraphs: ['Sendok kayu tua di dapur Vina retak di bagian tengah ketika dipakai mengaduk bubur. Danu membeli pengganti dari warung, dua sendok kayu baru yang masih berbau serutan. Vina mencoba sendok itu di panci bubur, mengaduk perlahan, dan merasa permukaannya cukup halus. Sendok lama ia simpan di tumpukan kayu bakar dekat tungku. Setelah bubur matang, mereka makan dengan sendok baru dan membicarakan harga jengkol di pasar. Vina mencuci sendok bekas pakai dan menaruhnya pada rak bumbu yang baru saja dibersihkan.'] },
      { chapterNumber: 45, title: 'Tirai Dapur Dicuci', paragraphs: ['Vina melepas tirai dapur yang kusam dan membawanya ke sungai belakang rumah untuk dicuci. Bu Ningsih datang membantu memeras, dan mereka membahas menu makan siang sekolah selama tirai direndam. Mereka menggosok noda minyak dengan sabut, membilas tirai dua kali, lalu menjemurnya di pagar depan. Tirai berkibar kena angin sampai kering menjelang sore. Bu Ningsih menolak dibayari dan pulang membawa seikat kangkung. Vina memasang tirai kembali pada kawat dan menghaluskan ujungnya dengan tangan, lalu menutup jendela dapur.'] },
      { chapterNumber: 46, title: 'Beras Dipindah Karung', paragraphs: ['Karung beras di dapur Vina terasa lembap di bagian bawah setelah hujan panjang. Vina mengeluarkan beras ke dalam tampah, memeriksa butiran yang menggumpal, lalu memindahkannya ke karung kering yang sudah dijemur. Ia menghitung takaran dengan kaleng susu dan mencatat angka di dinding kapur. Danu mengangkat karung baru ke sudut dapur yang lebih tinggi, mengganjalnya dengan papan. Vina menaburkan daun sereh di sekitar karung untuk mencegah kumbang. Mereka menutup karung dengan anyaman bambu dan menaruh batu di atasnya. Dapur kembali tampak seperti biasa.'] },
      { chapterNumber: 47, title: 'Piring Pecah Diganti', paragraphs: ['Kucing belang melompat ke meja saat Vina mencuci piring, menjatuhkan satu piring tanah ke lantai. Pecahan berserakan dekat kaki meja, dan Vina menyapunya dengan hati-hati memakai sapu lidi. Ia menimbang sisanya, tidak ada yang bisa direkat, lalu meminta piring baru kepada tetangga yang menjual tembikar. Piring pengganti berwarna kecokelatan dibawa pulang sore itu dan dicuci sebelum dipakai. Danu menaruh piring itu di tumpukan piring bersih sambil berkelakar bahwa kucing itu kini takut pada meja. Vina menyimpan pecahan lama di lubang sampah belakang dapur.'] },
      { chapterNumber: 48, title: 'Surat Kecamatan Tiba', paragraphs: ['Kurir bersepeda menurunkan surat beramplop resmi di rumah Vina siang hari, ditujukan untuk semua warga lereng. Vina membukanya dan membaca bahwa Bagas dipecat dari jabatan mandor lewat penyelidikan kota. Ia membaca surat itu dua kali, mencari nama sumber penyelidikan, tetapi tidak menemukannya. Ia menempelkan surat itu di dinding balai seperti diminta kepala desa. Warga datang bergantian membacanya sepanjang sore. Vina pulang dan menaruh topi kurir yang tertinggal di pagar, lalu masuk ke dapur untuk menyiapkan makan malam.'] },
      { chapterNumber: 49, title: 'Bubur Dimasak Seperti Biasa', paragraphs: ['Vina memasak bubur jagung di pagi hari memakai sendok kayu baru, mengaduknya pelan-pelan sampai mengental. Danu menata tiga toples berlabel di rak sambil membacakan berita keberangkatan Bagas dari koran bekas. Mereka membicarakan jadwal truk teh yang akan datang minggu depan dan harga karung kosong. Bubur dituang ke dua mangkuk, dan mereka makan sambil melihat kabut di luar jendela. Setelah sarapan, Danu pergi ke kebun dengan cangkul di bahu. Vina mencuci mangkuk, menyimpan sendok, dan menyapu lantai dapur.'] },
      { chapterNumber: 50, title: 'Dapur Tetap pada Tempatnya', paragraphs: ['Petugas baru membuka gerbang air dan membagikan jatah tanpa syarat kepada setiap kartu keluarga. Vina mengambil jatah di depan kantor bersama Danu, membawa pulang dua ember air. Ia menutup tirai dapur yang sudah dicuci, meletakkan piring baru di rak bumbu, dan mengisi toples garam dari kemasan. Danu menaruh ember di samping tempayan. Malam itu mereka memasak dengan air dari gerbang, dan lampu dapur menyala seperti biasa. Vina mematikan lampu setelah piring dibilas, menutup pintu dapur, dan masuk ke kamar.'] },
    ], justification: 'A sequence of self-contained kitchen chores prepares no dramatic answer; external officials resolve the conflict without using any runway setup.' },
    { chapters: [
      { chapterNumber: 41, title: 'Papan Cuaca Dicat Biru', paragraphs: ['Bu Ningsih membeli satu kaleng cat biru dari warung dan mengecat papan kayu bekas di halaman sekolah. Vina menulis tanggal pada sudut papan memakai kuas tipis sambil menahan papan dengan lutut. Cat mengering menjelang siang, meninggalkan bau minyak di udara. Mereka belum menentukan simbol apa yang akan dipakai untuk mencatat cuaca. Bu Ningsih mengusulkan tanda garis untuk hujan dan lingkaran untuk cerah. Vina menggambar dua contoh di tepi papan dengan kapur. Murid-murid mengintip dari jendela kelas sambil menebak maksud tanda itu.'] },
      { chapterNumber: 42, title: 'Satu Awan Digambar', paragraphs: ['Gerimis singkat turun setelah pelajaran pagi, dan seorang murid menggambar awan kapur pada papan cuaca. Vina menambahkan satu garis untuk arah angin di sudut papan memakai penggaris. Catatan pertama itu membuat papan tidak kosong lagi. Bu Ningsih menjelaskan bahwa satu hari belum cukup untuk menyimpulkan pola apa pun. Murid-murid bertepuk tangan melihat awan itu. Vina menghapus garis yang miring dan menggambar ulang dengan tangan yang lebih mantap. Sore hari hujan berhenti dan matahari menyinari papan sampai catnya terasa hangat.'] },
      { chapterNumber: 43, title: 'Angin Berubah Sore', paragraphs: ['Menjelang petang, angin berbalik arah dari timur ke barat, menggerakkan pita daun pisang yang dipasang di tiang papan. Vina menggambar garis kedua untuk mencatat arah baru itu, di sebelah garis yang dibuat pagi hari. Bu Ningsih membacakan catatan mereka sambil berkata bahwa data sebulan baru bisa dibandingkan. Dua garis itu tetap terpampang sampai hari berikutnya. Seorang murid bertanya mengapa angin bisa berpindah arah. Vina menjawab bahwa pegunungan dan lembah saling menarik udara secara bergantian. Murid itu mengangguk lalu kembali ke bangkunya.'] },
      { chapterNumber: 44, title: 'Hujan Tidak Dicatat', paragraphs: ['Hujan malam turun setelah sekolah tutup, membasahi halaman tanpa seorang pun memberi tanda pada papan cuaca. Pagi berikutnya Vina memperkirakan lamanya hujan dari genangan di tanah dan menulis tanda tanya di papan. Bu Ningsih menambahkan catatan kecil bahwa pengamatan malam sebaiknya dilakukan bergiliran. Murid-murid membandingkan genangan di bawah pagar dengan bekas hujan sore sebelumnya. Vina mengelap papan yang basah memakai kain lalu menuliskan tanggal baru. Tanda tanya itu dibiarkan utuh sampai siang. Anak-anak mulai berdebat tentang cara menghitung waktu hujan tanpa jam.'] },
      { chapterNumber: 45, title: 'Murid Membuat Simbol', paragraphs: ['Murid-murid berkumpul di depan papan dan menyepakati simbol matahari, kabut, dan gerimis menggantikan tanda sementara. Mereka berlatih menggambar simbol-simbol itu pada beberapa lembar kertas bekas, membandingkan hasil satu sama lain. Vina memilih gambar yang paling jelas dan menyalinnya pada papan sebagai contoh. Bu Ningsih menempelkan lembar latihan di dinding kelas. Seorang murid menggambar simbol gerimis dengan titik-titik yang terlalu rapat, lalu mengulangnya lebih renggang. Vina menyimpan sisa kertas latihan di kotak kapur. Sore itu papan memuat tiga simbol besar dan satu catatan tanggal.'] },
      { chapterNumber: 46, title: 'Papan Dipindah Teras', paragraphs: ['Angin kencang merobohkan papan cuaca pada pagi hari, dan dua tanda lama tergores saat papan jatuh ke tanah. Karsa datang membantu memindahkan papan ke teras kelas, memasang dua kaki tambahan dari bambu agar tidak roboh lagi. Vina menyalin tanda yang masih terbaca dengan kapur baru dan menghapus bagian yang rusak. Bu Ningsih menaruh batu di pangkal kaki papan sebagai penahan. Murid-murid menguji kestabilan papan dengan menggoyangkannya pelan-pelan. Papan itu berdiri di bawah atap teras, terlindung dari hujan langsung. Vina mengecat ulang tepi yang tergores dengan sisa cat biru.'] },
      { chapterNumber: 47, title: 'Kabut Dicatat Bersama', paragraphs: ['Kabut pagi menutupi halaman sekolah lebih tebal dari dua hari sebelumnya, dan tiga murid mencatatnya bersama-sama di papan cuaca. Mereka membandingkan ketebalan kabut dengan tulisan catatan lama, lalu menggambar simbol kabut sebanyak dua kali. Bu Ningsih menyimpan kapur sesudah kelas dan memasukkan pita pengukur ke laci guru. Vina menuliskan jam pengamatan pada sudut papan. Seorang murid menebak kabut akan bertahan sampai siang, sementara yang lain memperkirakan menghilang lebih cepat. Mereka menunggu sampai bel istirahat sambil mengamati langit dari teras.'] },
      { chapterNumber: 48, title: 'Audit Kantor Diumumkan', paragraphs: ['Pengumuman dari kecamatan ditempel di papan balai, menyebutkan audit kantor Bagas dimulai pekan ini setelah laporan dari kota diterima. Vina membacanya di gerbang sambil memegang kendi kosong, lalu menyalin tanggalnya di sela catatan sekolah. Bu Ningsih bertanya apakah catatan cuaca akan dipakai pemeriksa, dan Vina menjawab tidak tahu. Dua petugas meminta daftar jatah air dari kantor, bukan dari papan mereka. Vina tetap menulis satu simbol matahari pada papan sebelum pulang. Anak-anak memperhatikan mobil dinas dari jendela kelas sampai bel berbunyi.'] },
      { chapterNumber: 49, title: 'Tanda Matahari Memudar', paragraphs: ['Hujan pagi menghapus sebagian simbol matahari pada papan cuaca, meninggalkan lingkaran pucat yang sulit dikenali. Vina menebalkan tanda itu dengan kapur biru setelah kelas selesai. Danu bertanya dari balik pagar apakah papan akan dipakai lagi pada musim berikutnya. Vina menjawab mungkin, sambil menaruh kapur di kotak kayu dekat pintu kelas. Ia mengelap sisa air hujan dari permukaan papan dengan kain lap. Bu Ningsih menambahkan catatan tanggal di sudut papan. Menjelang sore, simbol matahari itu terlihat jelas dari halaman, meskipun cat lama di tepinya mulai mengelupas.'] },
      { chapterNumber: 50, title: 'Papan Cuaca Disimpan', paragraphs: ['Setelah Bagas dicopot dan jatah air dibuka oleh pejabat baru, sekolah memutuskan menyimpan papan cuaca di gudang selama masa libur panjang. Karsa membongkar kaki tambahan bambu, dan Vina membawa kapur serta penggaris pulang ke rumah. Bu Ningsih mencatat tanggal penyimpanan papan pada buku kecil, lalu melipat kertas simbol ke dalam amplop. Murid-murid membantu mengangkat papan ke sudut gudang di belakang dapur sekolah. Vina menggantung kain lap basah di pagar biar kering. Halaman sekolah kembali sunyi sampai anak-anak datang di pekan berikutnya.'] },
    ], justification: 'A modest weather-recording practice gains continuity but never connects to the central conflict, whose external resolution remains unearned.' },
  ],
  BORDERLINE: [
    { chapters: [
      { chapterNumber: 41, title: 'Tiga Rumah Menyimpan Air', paragraphs: ['Vina mencatat tiga rumah di lereng bawah yang masih menyimpan tempayan penuh air, menuliskan namanya pada sepotong kulit jagung dengan arang. Ia menggambar tanda silang di depan tiap rumah dan garis putus-putus menuju gerbang. Sebelum menyimpan catatan itu, ia menandai letak rumah dua lantai dengan lingkaran kosong karena belum yakin jumlah penghuninya. Kulit jagung itu digulung dan diikat tali di sudut dapur. Vina belum menanyakan kepada siapa pun apakah air boleh dibagi. Ia menggambar ulang peta itu dua kali supaya garisnya tidak tumpang tindih.'] },
      { chapterNumber: 42, title: 'Satu Tempayan Dipinjamkan', paragraphs: ['Bu Ningsih melihat gulungan kulit jagung di dapur Vina dan menawarkan setengah isi tempayannya untuk keluarga di seberang jalan. Vina membawa dua kendi tanah ke rumah Bu Ningsih, mengisi keduanya dari tempayan, lalu mengangkutnya memakai pikulan bambu. Ibu keluarga itu menerima air sambil tersenyum dan menyimpan kendi di bawah meja. Vina membuka catatan kulit jagung dan menambahkan satu titik di depan nama keluarga itu. Ia belum menulis jumlah air yang tersisa di tempayan Bu Ningsih. Sore itu matahari turun cepat dan bayangan pagar memanjang ke dapur.'] },
      { chapterNumber: 43, title: 'Kulit Jagung Hampir Robek', paragraphs: ['Hujan semalaman membuat kulit jagung yang disimpan di dapur menjadi lembap dan lunak. Vina membukanya keesokan pagi dan melihat satu nama di ujung catatan mulai memudar terkena air. Ia menyalin dua tanda silang yang masih jelas ke selembar kertas sekolah, tetapi tanda ketiga di sudut robek ikut hilang. Vina menjepit kertas baru di antara papan dan meminta Danu membawa pulang benang untuk mengganti tali pengikat. Ia memutuskan mencatat setiap kali hujan agar kertas tidak lagi basah. Malam itu kertas ditaruh di atas rak jauh dari tungku.'] },
      { chapterNumber: 44, title: 'Dua Ibu Menambah Titik', paragraphs: ['Dua ibu dari lereng tengah datang ke rumah Vina setelah mendengar ada catatan air. Mereka menyebut jumlah kendi yang dapat dipinjamkan, satu ibu menawarkan tiga kendi dan yang lain dua. Vina menambahkan titik-titik baru pada kertas dan menulis angka di samping tiap nama. Ia belum menghitung berapa anak atau orang tua yang membutuhkan lebih banyak air. Bu Ningsih mengusulkan mengumpulkan nama keluarga lain pada hari pasar. Vina menyimpan kertas itu di balik tempayan, berjanji menunjukkan peta kepada siapa pun yang datang.'] },
      { chapterNumber: 45, title: 'Bagas Melarang Pengangkutan', paragraphs: ['Bagas memasang papan larangan di dekat gerbang kantor: air tidak boleh dibawa melintasi jalan atas karena tumpahan membuat jalur licin. Dua ibu yang biasa lewat membatalkan rencana pengangkutan dan kembali membawa kendi kosong. Vina memindahkan satu pengiriman kecil melalui kebun kopi milik tetangga, menyusuri parit kering sampai ke rumah keluarga kedua. Rute itu lebih jauh dan menanjak. Setibanya di rumah, Vina menulis rute baru pada kertas catatan dan menggambar batu penanda di tengah jalan. Ia belum mengajak siapa pun mencoba rute itu bersama-sama.'] },
      { chapterNumber: 46, title: 'Kendi Pecah di Kebun', paragraphs: ['Di ujung jalur kebun, satu kendi tanah tergelincir dari pikulan Vina dan pecah di atas batu, airnya meresap ke tanah kering. Vina mengumpulkan pecahan kendi dan menguburnya di bawah pohon. Ia menandai lokasi pecah dengan coretan arang pada catatan, lalu menyelesaikan pengiriman memakai kendi yang tersisa. Keluarga penerima mendapat setengah porsi dan tetap berterima kasih. Karsa mendengar kejadian itu dan menawarkan membuatkan pikulan dengan penyangga melengkung. Vina mengukur jarak antar bahunya dengan tali dan menyerahkan ukuran itu kepada Karsa. Ia menyimpan satu keping pecahan sebagai tanda.'] },
      { chapterNumber: 47, title: 'Pikulan Pertama Dicoba', paragraphs: ['Karsa menyelesaikan pikulan dua sisi dengan penyangga melengkung dari kayu aren dan mengikat kendi dengan rotan. Vina mengisi dua kendi dan mengangkat pikulan ke bahunya, mencoba berjalan di jalur kebun tanpa tumpah. Tiga keluarga menerima bagian air pada hari itu tanpa menunggu giliran gerbang. Bu Ningsih meminta daftar kebutuhan sebelum pengiriman berikutnya, dan Vina menuliskan jumlah kendi per keluarga pada kertas. Karsa memperbaiki satu simpul yang longgar. Vina meletakkan pikulan di sudut dapur setelah matahari turun, kendi kosong berderak pelan.'] },
      { chapterNumber: 48, title: 'Audit Tidak Memakai Peta', paragraphs: ['Pemeriksa dari kecamatan datang dengan berkas lama yang dibawa dari kota dan langsung menyegel kantor Bagas. Mereka menanyakan daftar jatah air kepada juru tulis, bukan letak tempayan warga. Vina membawa kertas catatannya ke balai, tetapi tidak ada petugas yang memintanya. Dua ibu berdiri di pintu balai sambil memegang kendi kosong tanpa dipanggil masuk. Pemeriksa mencatat jumlah karung teh dan menutup ruang arsip dengan lakban. Vina melipat kertas catatannya dan menyimpannya di dalam lemari kecil. Warga pulang ke rumah masing-masing menjelang senja.'] },
      { chapterNumber: 49, title: 'Daftar Kebutuhan Belum Lengkap', paragraphs: ['Vina dan Bu Ningsih mencatat lima keluarga yang membutuhkan air pada kertas baru, lalu berhenti karena dua rumah di lereng atas tidak dapat ditemui. Jalan menuju rumah itu tertutup lumpur dari hujan semalam. Danu menawarkan membantu setelah giliran kerjanya selesai, membawa cangkul untuk membersihkan jalan. Vina menuliskan nama Danu pada daftar pembantu pengiriman. Bu Ningsih menyarankan menimbang kendi kosong untuk mengetahui ukuran porsi air. Vina mengangguk dan menyimpan kertas di balik toples. Karsa datang malam hari membawa pikulan kedua yang sudah diperkuat.'] },
      { chapterNumber: 50, title: 'Gerbang Dibuka Pejabat Baru', paragraphs: ['Pejabat baru membuka gerbang air seminggu setelah Bagas dicopot, dan warga antre membawa ember mulai pagi. Vina ikut mengambil dua ember air untuk rumahnya, lalu menaruh kertas catatan di balik toples garam untuk keadaan darurat. Pikulan buatan Karsa digantung di dinding dapur, kering dan siap dipakai. Bu Ningsih menyimpan daftar keluarga cadangan di lemari kelas. Beberapa ibu bertanya apakah catatan lama masih diperlukan, dan Vina menjawab untuk musim kering berikutnya. Malam itu air gerbang dimasak memakai tungku, dan uap memenuhi dapur sampai pintu ditutup.'] },
    ], justification: 'A small household-water network creates partial utility and future runway, but remains incomplete and does not earn the externally delivered resolution.' },
    { chapters: [
      { chapterNumber: 41, title: 'Bayang Renggang pada Daun', paragraphs: ['Bayang pagar jatuh pada daun talas di halaman Vina membentuk celah lebar yang tidak biasa. Vina mengambil arang dan menandai ujung bayang di pangkal daun, lalu menggambar garis kedua pada daun berikutnya sebagai pembanding. Ia menduga tiang pagar bergeser, tetapi belum mengukur tanah atau memanggil saksi. Ia mengamati bayang itu lagi pada siang hari dan mencatat bahwa celahnya tidak berubah meskipun matahari berpindah. Tanda arang itu ia tutup dengan daun kering supaya tidak terhapus angin. Malamnya ia bercerita kepada Danu sambil mencuci piring.'] },
      { chapterNumber: 42, title: 'Garis Arang Berpindah', paragraphs: ['Keesokan paginya, bayang pagar jatuh dua jari lebih jauh dari garis arang yang digambar Vina. Mbah Ripto yang lewat melihat perbedaan itu, berjongkok di dekat daun talas, dan menyarankan memasang tali ukur pada dua tiang. Mereka belum memasang tali karena atap dapur perlu diperbaiki lebih dulu. Vina menulis tanggal pengamatan pada batu kecil dengan arang. Mbah Ripto menekan tanah di sekeliling pangkal tiang dengan tumitnya untuk melihat apakah ada retakan. Vina menyimpan batu bertulis itu di bawah bangku. Mereka berjanji memasang tali setelah atap selesai ditambal.'] },
      { chapterNumber: 43, title: 'Tali Diikat Satu Tiang', paragraphs: ['Vina mengikat seutas tali dari tiang pagar ke batu dekat sumur dan menandai panjang awal dengan simpul benang merah. Ia menegangkan tali itu setiap sore untuk melihat apakah simpul bergeser. Ia belum memasang pembanding pada tiang lain. Mbah Ripto datang mengamati simpul merah itu dan berkata batu tetap perlu digali supaya tidak bergeser sendiri. Vina memadatkan tanah di sekitar batu dengan tumit. Sore itu simpul tidak berubah, dan Vina mencatatnya di kertas gulung.'] },
      { chapterNumber: 44, title: 'Simpul Menegang Sedikit', paragraphs: ['Sesudah truk berat lewat di jalan atas, tali ukur Vina terasa lebih tegang dan simpul merah bergeser sedikit, kira-kira selebar kuku. Bu Ningsih membantu mencatat waktu lewatnya truk dan posisi simpul pada kertas. Vina mengukur pergeseran itu dengan bilah bambu bertanda. Bagas menolak menghentikan kendaraan ketika diberi tahu, dengan alasan satu tali tidak cukup untuk mengubah jadwal angkut. Vina menggambar posisi baru simpul pada catatan sebelum hujan mengaburkan tanda di tanah. Ia meletakkan catatan itu di atas rak bumbu supaya tidak basah.'] },
      { chapterNumber: 45, title: 'Truk Lewat Sekali Lagi', paragraphs: ['Truk kedua melintas dua hari kemudian, dan tali ukur menegang sampai seratnya berbunyi saat Vina memegangnya. Ia segera memindahkan dua tempayan dari dekat tiang ke sisi dapur, mengangkatnya satu per satu. Keluarga lain tetap tinggal di rumah mereka karena belum ada jalur pengganti atau perintah dari siapa pun. Vina mengukur simpul merah dan menemukan pergeseran lebih besar dari sebelumnya. Ia menggambar tanda baru pada catatan dan menempelkan sehelai daun pada simpul sebagai penanda. Mbah Ripto melihat tali itu pada senja dan mengangguk tanpa berkata.'] },
      { chapterNumber: 46, title: 'Tali Putus Saat Hujan', paragraphs: ['Hujan deras semalaman memutus tali ukur dekat simpul merah, kedua ujung basah tergantung pada tiang dan batu. Vina menyimpan kedua ujung itu dalam kantong kain sebagai bukti, tetapi panjang aslinya tidak dapat diukur lagi. Mbah Ripto dan Bu Ningsih memeriksa ujung putus itu di bawah teras. Pemeriksa desa berkata catatan mereka patut diperhatikan namun belum cukup menetapkan larangan kendaraan berat di jalan itu. Vina menggambar tali putus pada kertas dan menulis waktu putusnya. Ia menggantung kantong bukti di paku dekat pintu.'] },
      { chapterNumber: 47, title: 'Dua Tiang Baru Dipasang', paragraphs: ['Karsa memasang dua tiang bambu pembanding di sisi jauh dari jalan, mengikatnya pada batu dengan pasak kayu. Vina mengikat tali baru dari tiang pertama ke tiang kedua, memberi simpul putih pada panjang awal. Ia mencatat posisi simpul pada kertas baru dan mengajak murid-murid melihat dari jarak aman di pagar sekolah. Bu Ningsih menulis nama murid yang ikut mengamati. Dua hari pertama simpul putih tidak bergeser. Vina mengukur tali itu sebelum matahari tenggelam dan menyimpan catatan di balik rak bumbu. Mbah Ripto menambahkan satu simpul pembanding sesuai sarannya sendiri.'] },
      { chapterNumber: 48, title: 'Pengemudi Memilih Jalan Kebun', paragraphs: ['Seorang pengemudi truk menghentikan kendaraannya di tikungan, melihat tiang pembanding yang miring, lalu memilih jalan kebun atas kemauan sendiri. Vina melihat dari teras dan mencatat waktu kendaraan berbelok. Bagas memotong upah harian pengemudi itu keesokan harinya dan memasang papan larangan memakai jalan kebun. Dua pengemudi lain tetap memakai jalan atas tanpa menoleh ke tiang. Vina menggambar rute jalan kebun pada catatan dan mengarsir bagian berlumpur. Bu Ningsih menanyakan apakah pengemudi lain akan mengikuti contoh itu. Vina menjawab ia belum tahu, lalu menyimpan catatan di rak bumbu.'] },
      { chapterNumber: 49, title: 'Catatan Baru Baru Dua Hari', paragraphs: ['Dua hari pengukuran pada tiang baru menunjukkan gerak kecil pada satu simpul putih di sisi timur. Vina membawa catatan itu ke kantor dan meminta penundaan truk selama seminggu. Petugas memberi waktu tiga hari untuk bukti tambahan, tidak lebih. Vina memasang tali lebih kencang dan menandai posisi simpul setiap sore. Ia belum membahas risiko pekerjaan ini dengan Danu, meskipun kakaknya ikut memperkuat pasak. Mbah Ripto menyarankan menimbang beban truk di jalan kebun. Vina menulis pertanyaan itu di tepi kertas, lalu melipat lembaran itu dan menaruhnya di rak atas.'] },
      { chapterNumber: 50, title: 'Jalan Ditutup Sementara', paragraphs: ['Kecamatan menutup jalan berat selama dua pekan sambil menunggu pengukuran lengkap dari catatan Vina. Truk beralih sementara ke jalan kebun, dan dua papan jembatan kecil diperkuat oleh Karsa. Sumur di dekat tiang belum rusak, dan air tetap jernih. Vina menyimpan tali putus serta catatan baru di dalam kantong kain yang digantung dekat pintu. Mbah Ripto mengukur simpul putih setiap pagi dan melaporkan hasilnya tanpa menulis. Bu Ningsih mencatat tanggal pembukaan kembali pada papan kelas. Warga mulai terbiasa mendengar suara truk di jalan kebun menjelang sore.'] },
    ], justification: 'Incremental shadow and rope measurements earn a temporary closure, yet incomplete evidence and unresolved family costs keep the ending only partially satisfying.' },
    { chapters: [
      { chapterNumber: 41, title: 'Bau Besi dari Mata Air', paragraphs: ['Vina mencium bau besi pada mata air kecil di kebun kopi dan mengisi satu botol bening dengan air dari pancurannya. Ia menutup botol dengan kain dan meletakkannya di keranjang. Ia belum tahu apakah perubahan berasal dari pipa kantor atau tanah setelah hujan. Vina membandingkan bau air botol itu dengan air kendi rumah, dan keduanya berbeda. Ia menggambar letak mata air di halaman kertas dan menandai arah pancuran memakai arang. Botol itu ia simpan di sudut dapur yang teduh, jauh dari tungku. Ia belum memberi tahu siapa pun tentang temuan ini.'] },
      { chapterNumber: 42, title: 'Endapan Jingga Terbentuk', paragraphs: ['Semalam kemudian, lapisan endapan jingga tipis muncul di dasar botol bening yang disimpan Vina. Karsa melihat endapan itu saat mampir membawa bibit dan menyarankan mengambil sampel dari dua titik lain di sepanjang aliran. Vina hanya memiliki satu botol kosong, sehingga ia berencana meminjam dari Bu Ningsih. Keduanya membandingkan warna endapan dengan tanah merah di tepi kebun. Karsa mencium bau botol itu dan mengerutkan dahi. Vina menulis tanggal terbentuknya endapan pada kertas catatan. Ia menggantung botol di tempat teduh supaya matahari tidak mengubah isinya.'] },
      { chapterNumber: 43, title: 'Botol Kedua dari Hulu', paragraphs: ['Bu Ningsih meminjamkan sebuah botol kaca bekas kecap, dan Vina mengambil air dari mata air hulu dekat pagar kebun. Sampel kedua itu tetap jernih sampai malam, tanpa endapan di dasarnya. Vina meletakkan dua botol berdampingan dan membandingkan warnanya di bawah cahaya lampu. Perbedaan tersebut menunjukkan perubahan terjadi di antara dua titik, tetapi wilayahnya masih mencakup kebun yang luas. Vina menggambar garis lurus di antara kedua mata air pada kertas dan menaruh tanda tanya di bagian tengah. Karsa menyarankan menyusuri aliran pada akhir pekan. Vina mengangguk sambil menutup botol.'] },
      { chapterNumber: 44, title: 'Pakis Menutup Pipa', paragraphs: ['Di lereng antara dua mata air, Vina menemukan rumpun pakis yang tertekan seolah menutupi sesuatu. Ia mengangkat satu daun dan melihat ujung benda hijau seperti pipa, lalu berhenti agar lokasi tidak rusak. Karsa mengamati dari kejauhan dan menggambar posisi pakis pada catatan. Bagas memasang larangan masuk kebun sore itu juga, dengan alasan kru sedang memangkas. Vina menyembunyikan catatan di balik tampah sebelum petugas lewat. Ia dan Karsa tidak kembali ke lokasi sampai seminggu kemudian. Bu Ningsih diberi tahu dengan suara pelan di teras sekolah.'] },
      { chapterNumber: 45, title: 'Lokasi Difoto dengan Arang', paragraphs: ['Bu Ningsih menggambar posisi pakis, batu, dan kedua mata air pada papan kayu kecil memakai arang, lengkap dengan tanda arah aliran. Mereka tidak dapat mendekati benda hijau karena dua pekerja berjaga di dekat kantor sejak pagi. Gambar itu menjaga orientasi dan dapat dibagikan kepada siapa pun tanpa membawa orang ke lokasi. Vina menyalin gambar ke kertas dan menulis keterangan jarak antara dua mata air. Karsa menambahkan tanda tempat ia melihat pakis bergoyang. Papan kayu itu disimpan di rak kelas Bu Ningsih. Sore hari Vina menggambar ulang agar arangnya tidak luntur.'] },
      { chapterNumber: 46, title: 'Hujan Menggeser Pakis', paragraphs: ['Hujan deras semalaman menggeser pakis basah dan memperlihatkan pipa pendek yang berakhir di tanah lembap. Vina memanggil dua ibu dari rumah terdekat, tetapi aliran dari pipa sudah berhenti sebelum mereka tiba. Mereka melihat bentuk pipa dan bekas basah di sekelilingnya tanpa dapat mengambil cairan. Vina menggambar pipa itu pada catatan dan menulis arah ujungnya. Karsa mengangkat satu ruas pipa dengan hati-hati lalu meletakkannya kembali. Bu Ningsih menyarankan melaporkan temuan itu ke kecamatan. Vina menggulung catatan dan menjepitnya dengan tali setelah dua ibu pulang.'] },
      { chapterNumber: 47, title: 'Pipa Dibawa Kecamatan', paragraphs: ['Dua petugas kecamatan mencabut ruas pipa hijau dan membungkusnya dengan kain sebelum dibawa ke kantor. Bagas menyatakan pipa itu saluran pupuk lama yang terbengkalai sejak dua musim lalu. Vina menyerahkan dua botol sampel, gambar papan arang, dan daftar saksi kepada petugas. Pemeriksa menerima semuanya dan mencatat nama setiap saksi dalam buku. Ia mengatakan hasil uji baru keluar setelah sidang penempatan mandor selesai. Vina meminta tanda terima, dan petugas menuliskan nomor berkas pada secarik kertas. Karsa menyimpan salinan catatan di bengkelnya. Bu Ningsih menunggu di gerbang sampai petugas pergi.'] },
      { chapterNumber: 48, title: 'Gerbang Dibuka Sementara', paragraphs: ['Kantor membuka jatah air tambahan sementara agar warga berhenti memakai mata air kebun. Vina mengambil jatah itu di gerbang bersama ibu lain, dua ember setiap keluarga. Air tambahan membantu beberapa rumah, tetapi membuat sampel baru sulit diperoleh karena mata air mulai sepi dipakai. Vina memilih menyimpan dua botol lama dan menulis catatan bahwa sampel segar tidak lagi tersedia. Karsa melihat aliran kebun dari kejauhan tanpa mendekat. Bu Ningsih menyarankan menimbang ember jatah untuk menghitung air yang diterima setiap keluarga. Vina mencatat hasil penimbangan di kertas sebelum pulang.'] },
      { chapterNumber: 49, title: 'Hasil Uji Belum Datang', paragraphs: ['Malam sebelum sidang penempatan mandor, hasil uji pipa belum tiba di balai. Vina duduk di teras sekolah bersama Bu Ningsih dan mengakui bahwa ia ingin satu temuan menyelesaikan seluruh perkara. Bu Ningsih mengingatkan bahwa penyelidikan dapat benar meskipun belum lengkap. Vina menata berkas di tas kain: dua botol, gambar papan, catatan pengukuran, dan daftar saksi. Ia mengikat berkas itu dengan benang dan meletakkannya di samping tungku. Karsa datang membawa kabar bahwa truk kantor lewat membawa dokumen. Vina mengangguk tanpa membuka tasnya.'] },
      { chapterNumber: 50, title: 'Mandor Dipindah Sementara', paragraphs: ['Kecamatan memindahkan Bagas sementara ke dinas lain berdasarkan pelanggaran akses, bukan karena pencemaran yang belum terbukti. Mata air ditutup sampai hasil uji keluar, dan warga menerima jatah tambahan dari gerbang. Vina menyimpan dua botol sampel di rak dapur bersama berkas catatan. Bu Ningsih menempelkan surat pemindahan di papan balai. Karsa membersihkan pipa hijau yang tertinggal di semak dan menaruhnya di gudang desa. Sumber endapan, tanggung jawab, dan masa depan pipa belum diumumkan. Vina menulis tanggal sidang berikutnya di tepi berkas, lalu menggantung tas kain di paku dekat pintu.'] },
    ], justification: 'A bounded contamination investigation earns temporary protection and removal, but delayed testing leaves causation and durable resolution incomplete.' },
  ],
}
